def para(text, bold=False, align=None):
    p=doc.add_paragraph()
    p.add_run(text).bold=bold
    if align is not None: p.alignment=align
    else: p.paragraph_format.first_line_indent=Cm(1.25)
    return p

def heading(text, level=1):
    p=doc.add_paragraph(text, f'Heading {level}')
    if level==1: p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    contents.append(text)
    return p

def bullets(items):
    for t in items:
        p=doc.add_paragraph('• '+t)
        p.paragraph_format.left_indent=Cm(.5)
        p.paragraph_format.first_line_indent=Cm(-.5)

