def table(number,title,rows):
    if number>1: page()
    p=para(f'Таблица {number} — {title}',align=WD_ALIGN_PARAGRAPH.RIGHT)
    p.paragraph_format.keep_with_next=True
    p.paragraph_format.line_spacing=1
    tbl=doc.add_table(rows=1, cols=5)
    tbl.style='Table Grid'; tbl.autofit=False
    widths=[.7,3.05,5.05,5.05,3.15]
    for c,w in zip(tbl.columns,widths): c.width=Cm(w)
    labels=['№','Проверяемое действие','Действия проверяющего в интерфейсе','Ожидаемый результат','Результат, полученный в ходе испытания']
    for c,t in zip(tbl.rows[0].cells,labels): c.text=t
    repeat=OxmlElement('w:tblHeader'); tbl.rows[0]._tr.get_or_add_trPr().append(repeat)
    for n,row in enumerate(rows,1):
        cells=tbl.add_row().cells
        for c,t in zip(cells,[str(n),*row,'']): c.text=t
    for idx,row in enumerate(tbl.rows):
        no_split=OxmlElement('w:cantSplit'); row._tr.get_or_add_trPr().append(no_split)
        for c,w in zip(row.cells,widths):
            c.width=Cm(w)
            for p in c.paragraphs:
                p.alignment=WD_ALIGN_PARAGRAPH.LEFT
                p.paragraph_format.line_spacing=1.1
                p.paragraph_format.space_after=Pt(5)
                p.paragraph_format.space_before=Pt(5)
                for r in p.runs: r.font.size=Pt(12); r.bold=idx==0
for n,(title,rows) in enumerate(TABLES,1): table(n,title,rows)
